
import DataService from '../../services/DataService';

export function urlBase64ToUint8Array(base64String) {
    const padding = '='.repeat((4 - base64String.length % 4) % 4);
    const base64 = (base64String + padding).replace(/-/g, '+').replace(/_/g, '/');
    const rawData = window.atob(base64);
    return new Uint8Array([...rawData].map(char => char.charCodeAt(0)));
}

export async function subscribeUser(vapidPublicKey, serviceWorkerPath = '/content/worker.js', platform = 'Web') {
    if (!('serviceWorker' in navigator) || !('PushManager' in window)) {
        console.log('Push notifications not supported.');
        return null;
    }
    const permission = await Notification.requestPermission();
    if (permission !== 'granted') {
        console.log('Notification permission denied.');
        return null;
    }
    try {
        const registration = await navigator.serviceWorker.register(serviceWorkerPath);
        const subscription = await registration.pushManager.subscribe({
            userVisibleOnly: true,
            applicationServerKey: urlBase64ToUint8Array(vapidPublicKey)
        });
        const payload = {
            Platform: platform,
            Token: JSON.stringify(subscription)
        };
        const response = await DataService.SavePlatformDetail(payload);
        if (response?.data) {
            console.log('Subscription saved:', response.data);
        }
    } catch (error) {
        console.error('Subscription error:', error);
        return null;
    }
}

