// Add response interceptor for handling token expiration
const setupResponseInterceptor = (axiosInstance) => {
    axiosInstance.interceptors.response.use(
        (response) => response,
        async (error) => {
            const originalRequest = error.config;

            // If the error is 401 and we haven't already tried to refresh
            if (error.response?.status === 401 && !originalRequest._retry) {
                originalRequest._retry = true;

                try {
                    // Dynamically import authService to avoid circular dependency
                    const authService = (await import('./services/authservice.js')).default;
                    
                    // Try to refresh the token
                    const user = await authService.refreshUser();
                    
                    if (user && user.access_token) {
                        // Update the authorization header with the new token
                        originalRequest.headers['Authorization'] = `Bearer ${user.access_token}`;
                        
                        // Retry the original request
                        return axiosInstance(originalRequest);
                    }
                } catch (refreshError) {
                    console.error('Token refresh failed:', refreshError);
                    
                    // Redirect to login if refresh fails
                    const authService = (await import('./services/authservice.js')).default;
                    authService.signIn(window.location.pathname);
                    
                    return Promise.reject(refreshError);
                }
            }

            return Promise.reject(error);
        }
    );
};

// Apply response interceptor to all instances
setupResponseInterceptor(instance);
setupResponseInterceptor(instanceCommon);
setupResponseInterceptor(instanceProject);
setupResponseInterceptor(instanceTimer);
setupResponseInterceptor(instanceTimerModals);
setupResponseInterceptor(instanceAsset);

export default {instance,instanceCommon,instanceProject,instanceTimer,instanceTimerModals,instanceAsset};
