        BindActionButtonEvent: function () {
            let actionButtons = document.getElementsByClassName("action_icon");
        
            for (let index = 0; index < actionButtons.length; index++) {
                const button = actionButtons[index];
        
                button.addEventListener("click", function (e) {
                    e.stopPropagation(); // Prevent event bubbling
        
                    // Close all other action boxes
                    document.querySelectorAll(".action-list-box.is-visible").forEach(function (box) {
                        box.classList.remove("is-visible");
                        box.style.opacity = 0;
                        box.style.width = 0;
                    });
        
                    // Open only the clicked one
                    let actionBox = button.nextElementSibling;
                    if (actionBox) {
                        actionBox.classList.add("is-visible");
                        actionBox.style.opacity = 1;
                        
                        // Calculate width dynamically
                        let width = 340; // Start with a base width
                        actionBox.querySelectorAll(".actions-onclick").forEach(function (element) {
                            width += element.clientWidth + 10;
                        });
        
                        let pos = 0;
                        let id = setInterval(frame, 5);
                        function frame() {
                            if (pos >= width) {
                                clearInterval(id);
                            } else {
                                pos += 5;
                                actionBox.style.width = pos + "px";
                            }
                        }
                    }
                });
        
                // Close the action box when clicking on the close button
                let closeButton = button.nextElementSibling?.querySelector(".close-action");
                if (closeButton) {
                    closeButton.addEventListener("click", function (e) {
                        e.stopPropagation();
                        let actionBox = button.nextElementSibling;
                        if (actionBox) {
                            actionBox.classList.remove("is-visible");
                            actionBox.style.opacity = 0;
                            actionBox.style.width = 0;
                        }
                    });
                }
            }
        
            // Close any open action box when clicking outside
            document.addEventListener("click", function () {
                document.querySelectorAll(".action-list-box.is-visible").forEach(function (box) {
                    box.classList.remove("is-visible");
                    box.style.opacity = 0;
                    box.style.width = 0;
                });
            });
        },
