//Get format 00:00:00 from second
export const formatter = (sec = 0) => {
    const seconds = Math.abs(sec)
    const d = Number(seconds);
    const h = Math.floor(d / 3600);
    const m = Math.floor((d % 3600) / 60);
    const s = Math.floor((d % 3600) % 60);
    const hDisplay = h > 0 ? `${h.toString().length > 1 ? `${h}` : `${0}${h}`}` : '00';
    const mDisplay = m > 0 ? `${m.toString().length > 1 ? `${m}` : `${0}${m}`}` : '00';
    const sDisplay = s > 0 ? `${s.toString().length > 1 ? `${s}` : `${0}${s}`}` : '00';
    return `${sec < 0 ? "-" : ""}${hDisplay}:${mDisplay}:${sDisplay}`;
};
//Get diff according to getIn second,hours,minutes
export const getSecondsFromDate = (obj, getIn) => {
    const startDateMomentFormat = moment(new Date(obj.startDate), "DD/MM/YYYY HH:mm:ss").format("YYYY-MM-DD HH:mm:ss");
    const endDateMomentFormat = moment(new Date(obj.endDate), "DD/MM/YYYY HH:mm:ss").format("YYYY-MM-DD HH:mm:ss");
    const startDate = moment(startDateMomentFormat);
    const nowDate = moment(endDateMomentFormat);
    let timerSec = nowDate.diff(startDate, getIn)
    return timerSec
}
//Convert Time to Seconds
export const timeToSeconds = (hms) => {

    let hour = hms + ":00"
    const [hours, minutes, seconds] = hour.split(':');
    return Number(hours) * 60 * 60 + Number(minutes) * 60 + Number(seconds);
}
// Get Today Yesterday and date
export const getPreviousDay = (date = moment()) => {
    const getDate = moment(new Date(date), 'DD/MM/YYYY').format('YYYY-MM-DD')
    const Yesterday = moment().subtract(1, 'day').format('YYYY-MM-DD')
    const today = moment().endOf('day').format('YYYY-MM-DD')
    if (getDate == today) return 'Today'
    if (getDate == Yesterday) return 'Yesterday'
    return moment(new Date(date), 'DD/MM/YYYY').format('ddd, MMM DD')
}
export const dateConverter = (date) => {
    return moment(new Date(date), 'DD/MM/YYYY').format('YYYY-MM-DD')
}
export const dateTimeConverter = (date) => {
    return moment(new Date(date), 'DD/MM/YYYY HH:mm:ss').format('YYYY-MM-DD HH:mm:ss')
}

export function ShowAlert(message, type, showtitle, title, isHide) {
    if (!type || type == null || type == "" || typeof (type) == "undefined") {
        type = "success";
    }

    $("div#notifymessage").show().find(".msg").removeClass("alert-success").removeClass("alert-danger").removeClass("alert-warning");
    var isHeader = false;
    if ($("div#notifymessage").find(".hdr").length > 0) {
        isHeader = true;
        $("div#notifymessage").find(".hdr").removeClass("alert-success-header").removeClass("alert-danger-header").removeClass("alert-warning-header");
    }
    if (showtitle && isHeader) {
        $("div#notifymessage").find(".hdr h4").html(title);
        $("div#notifymessage").find(".hdr h4").hide();
    }
    if (type.toLowerCase() == "success") {
        if (isHeader) {
            $("div#notifymessage").find(".hdr").addClass("alert-success-header");
        }
        $("div#notifymessage").find(".msg").addClass("alert-success").find("span:first").html(message);
    }
    else if (type.toLowerCase() == "warning") {
        if (isHeader) {
            $("div#notifymessage").find(".hdr").addClass("alert-warning-header");
        }
        $("div#notifymessage").find(".msg").addClass("alert-warning").find("span:first").html(message);
    }
    else {
        if (isHeader) {
            $("div#notifymessage").find(".hdr").addClass("alert-danger-header");
        }
        $("div#notifymessage").find(".msg").addClass("alert-danger").find("span:first").html(message);
    }
    if (isHide || type == "success") {
        setTimeout(function () {
            $('div#notifymessage').hide();
        }, 3000);
    }
    $("body").on("click", "#closenotifymessage", function () {
        $("#notifymessage").hide().find(".msg span:first").html('');
    });
}
export const dateFormat = "YYYY-MM-DD"
export const dateTimeFromat = "YYYY-MM-DD HH:mm:ss"
